  "Reciprocity": {"Explanation": "The email asks the recipient to take an action (check payment details and confirm account) in return for a favor (getting back the benefits of their account)."},
  "Scarcity": {"Explanation": "The email creates a sense of urgency by implying that the account has been limited due to security reasons, and the recipient needs to take action to get back the benefits."},
  "Authority": {"Explanation": "The email claims credibility through a recognized institution (Uber) and a French company (S.A.R.L. etc.), which adds to its authority."},
  "Commitment/Consistency": {"Explanation": "The email references the recipient's preferences (indicate that they'd like to receive email communications about news) to push further action (choosing which communications to receive)."},
  "Liking": {"Explanation": "The email uses personalization by addressing the recipient by their name (Ayoub) and referencing their preferences, which builds a sense of familiarity and rapport."},
  "Social proof": {"Explanation": "Not present"}
}

